def load_shop_catalogue(shop_dir) -> List[Dict[str, Any]]:
    """Read the shop's supply catalogue from JSON files in `shop/`.

    Every ``*.json`` file (names starting with ``_`` are skipped, so
    templates survive) may hold one supply object, a list of supplies, or
    the wrapped ``{"items": [...]}`` format. Each supply needs a name and
    a positive price; the id defaults to the file stem. Bad files are
    skipped so one mistake cannot empty the shop. Returns [] when the
    folder is missing or holds nothing usable."""
    folder = Path(shop_dir)
    if not folder.is_dir():
        return []
    catalogue: List[Dict[str, Any]] = []
    seen_ids: set = set()

    def _add(entry: Any, default_id: str):
        if not isinstance(entry, dict):
            return
        name = str(entry.get("name") or "").strip()
        if not name:
            return
        try:
            price = int(entry.get("price", 0) or 0)
        except (TypeError, ValueError):
            return
        if price <= 0:
            return
        supply_id = str(entry.get("id") or default_id).strip()
        if supply_id in seen_ids:
            return
        seen_ids.add(supply_id)
        catalogue.append({
            "id": supply_id,
            "name": name,
            "price": price,
            "description": str(entry.get("description") or ""),
        })

    for file_path in sorted(folder.iterdir()):
        if (not file_path.is_file()
                or file_path.suffix.lower() != ".json"
                or file_path.name.startswith("_")):
            continue
        try:
            data = json.loads(file_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        stem = file_path.stem
        if isinstance(data, list):
            for entry in data:
                _add(entry, stem)
        elif isinstance(data, dict) and isinstance(data.get("items"), list):
            for entry in data["items"]:
                _add(entry, stem)
        else:
            _add(data, stem)
    return catalogue


class InventoryManager:
    """Owns the artifact database: earned artifacts plus the shop's stock."""

    SHOP_STOCK_SIZE = 6
    PACKAGE_SIZE = 10      # artifacts in the shop's bulk common package
    PACKAGE_PRICE = 400    # gold for the package

    def __init__(
        self,
        items_dir: str,
        library_dir: str,
        cache_dir: str,
        rp_root: str,
        shop_dir: str | None = None,
    ):
        self.items_dir = Path(items_dir)
        self.library_dir = Path(library_dir)
        self.cache_dir = Path(cache_dir)
        self.rp_root = Path(rp_root)
        self.shop_dir = Path(shop_dir) if shop_dir is not None else self.rp_root / "shop"

        self.items_dir.mkdir(parents=True, exist_ok=True)
        self.cache_dir.mkdir(parents=True, exist_ok=True)

        # The shop sells whatever the JSON files in shop/ define; the
        # built-in list below is the fallback when that folder is empty.
        self.supplies = load_shop_catalogue(self.shop_dir) or list(SUPPLIES)

        self.generator = ArtifactGenerator(library_dir)
        self.db_path = self.cache_dir / "inventory.db"
        self._init_db()

    # --- Database ---
    def _init_db(self):
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute(_ARTIFACTS_SQL)
            # --- migrate databases from earlier artifact systems ---
            cols = {row[1] for row in conn.execute("PRAGMA table_info(artifacts)")}
            legacy = False
            if "source" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN source TEXT DEFAULT 'legacy'")
                legacy = True
            if "description" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN description TEXT DEFAULT ''")
            if "story" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN story TEXT DEFAULT ''")
            if "upgrade_level" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN upgrade_level INTEGER DEFAULT 0")
            if "upgrade_log" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN upgrade_log TEXT DEFAULT '[]'")
            if legacy:
                # Old rows were blind auto-seeds built from empty word lists
                # (twenty "Unknown Relic"s) — the new system starts clean.
                conn.execute("DELETE FROM artifacts WHERE source = 'legacy'")
            if "adjective" in cols:
                # The adjective-based generator kept a dedicated column —
                # rebuild the table without it, keeping the row ids so
                # mission credits still point at the same artifacts.
                conn.execute("ALTER TABLE artifacts RENAME TO artifacts_old")
                conn.execute(_ARTIFACTS_SQL)
                conn.execute("""
                    INSERT INTO artifacts
                        (id, name, item_type, rarity, level, stats, source, description, story, created_at)
                    SELECT id, name, item_type, rarity, level, stats, source, description, story, created_at
                    FROM artifacts_old
                """)
                conn.execute("DROP TABLE artifacts_old")
            conn.execute(_SUPPLIES_SQL)
            conn.execute(_SHOP_STOCK_SQL)
            shop_cols = {row[1] for row in conn.execute("PRAGMA table_info(shop_stock)")}
            if "adjective" in shop_cols:
                # Same rebuild for the shop shelves.
                conn.execute("ALTER TABLE shop_stock RENAME TO shop_stock_old")
                conn.execute(_SHOP_STOCK_SQL)
                conn.execute("""
                    INSERT INTO shop_stock
                        (id, name, item_type, rarity, level, stats, price, description, story, created_at)
                    SELECT id, name, item_type, rarity, level, stats, price, description, story, created_at
                    FROM shop_stock_old
                """)
                conn.execute("DROP TABLE shop_stock_old")
            conn.commit()

    @staticmethod
    def _parse_stats(raw: Any) -> Dict[str, Any]:
        try:
            data = json.loads(raw or "{}")
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    # --- Artifacts (generate / read / delete) ---
    def _insert_artifact(self, conn, payload: Dict[str, Any]) -> int:
        cur = conn.execute("""
            INSERT INTO artifacts
                (name, item_type, rarity, level, stats, source, description, story,
                 upgrade_level, upgrade_log)
            VALUES
                (:name, :item_type, :rarity, :level, :stats, :source, :description, :story,
                 :upgrade_level, :upgrade_log)
        """, {
            "name": payload.get("name", ""),
            "item_type": payload.get("item_type", ""),
            "rarity": payload.get("rarity", "Common"),
            "level": payload.get("level", 1),
            "stats": payload.get("stats", "{}"),
            "source": payload.get("source", "mission"),
            "description": payload.get("description", ""),
            "story": payload.get("story", ""),
            "upgrade_level": int(payload.get("upgrade_level", 0) or 0),
            "upgrade_log": payload.get("upgrade_log", "[]"),
        })
        return int(cur.lastrowid or 0)

    def _row_to_item(self, row) -> InventoryItem:
        return InventoryItem(
            uid=f"artifact:{row['id']}",
            name=row["name"],
            category="artifact",
            item_type=row["item_type"],
            description=row["description"] or f"A {row['rarity']} {row['item_type']}.",
            story=row["story"] or "",
            rarity=row["rarity"],
            image_path="",
            stats=self._parse_stats(row["stats"]),
            count=1,
            level=row["level"],
            source_file=str(self.db_path),
            source=row["source"] or "",
            upgrade_level=int(row["upgrade_level"] or 0) if "upgrade_level" in row.keys() else 0,
            upgrade_log=self._parse_upgrade_log(row["upgrade_log"]) if "upgrade_log" in row.keys() else [],
        )

    @staticmethod
    def _parse_upgrade_log(raw: Any) -> List[Dict[str, Any]]:
        try:
            data = json.loads(raw or "[]")
            return data if isinstance(data, list) else []
        except Exception:
            return []

    def generate_artifacts(self, count: int = 1, rarity: Optional[str] = None,
                           difficulty: Optional[str] = None, level: int = 1,
                           source: str = "mission") -> List[InventoryItem]:
        """Roll `count` new artifacts, store them, and return them as items.
        Artifacts have no level — the `level` argument is accepted for
        compatibility and ignored."""
        items: List[InventoryItem] = []
        with sqlite3.connect(str(self.db_path)) as conn:
            for _ in range(max(0, count)):
                a = self.generator.generate(rarity=rarity, difficulty=difficulty)
                payload = {
                    "name": a["name"],
                    "item_type": a["item_type"],
                    "rarity": a["rarity"],
                    "level": a["level"],
                    "stats": json.dumps(a["stats"]),
                    "source": source,
                    "description": a["description"],
                    "story": a["story"],
                }
                new_id = self._insert_artifact(conn, payload)
                items.append(InventoryItem(
                    uid=f"artifact:{new_id}",
                    name=a["name"],
                    category="artifact",
                    item_type=a["item_type"],
                    description=a["description"],
                    story=a["story"],
                    rarity=a["rarity"],
                    image_path="",
                    stats=a["stats"],
                    count=1,
                    level=a["level"],
                    source_file=str(self.db_path),
                    source=source,
                ))
            conn.commit()
        return items

    def delete_artifacts(self, ids: List[Any]):
        """Remove artifacts by id — used to revoke mission rewards."""
        clean: List[int] = []
        for value in ids or []:
            try:
                clean.append(int(value))
            except (TypeError, ValueError):
                continue
        if not clean:
            return
        with sqlite3.connect(str(self.db_path)) as conn:
            placeholders = ",".join("?" * len(clean))
            conn.execute(f"DELETE FROM artifacts WHERE id IN ({placeholders})", clean)
            conn.commit()

    # --- Workshop (upgrade / reroll) ---
    def get_artifact_by_id(self, artifact_id: Any) -> Optional[InventoryItem]:
        """Fetch one artifact row by its numeric id."""
        try:
            aid = int(artifact_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM artifacts WHERE id = ?", (aid,)).fetchone()
        return self._row_to_item(row) if row is not None else None

    def get_equipped_artifacts(self, equipped_ids) -> List[InventoryItem]:
        """The equipped artifacts in slot order; missing ids are skipped."""
        items: List[InventoryItem] = []
        for value in equipped_ids or []:
            try:
                aid = int(value)
            except (TypeError, ValueError):
                continue
            item = self.get_artifact_by_id(aid)
            if item is not None:
                items.append(item)
        return items

    def upgrade_artifact(self, artifact_id: Any) -> Optional[Dict[str, Any]]:
        """Apply one workshop upgrade: a low/mid/high roll into a random
        stat, growing a little per upgrade level already on the artifact.

        Returns {'item', 'stat', 'amount', 'tier', 'high', 'cost'} on
        success, or None when the artifact is missing, already maxed, or
        has no stats to grow."""
        try:
            aid = int(artifact_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM artifacts WHERE id = ?", (aid,)).fetchone()
            if row is None:
                return None
            stats = self._parse_stats(row["stats"])
            upgrade_level = int(row["upgrade_level"] or 0)
            if upgrade_level >= MAX_UPGRADE_LEVEL or not stats:
                return None
            rarity = row["rarity"]
            stat = random.choice(list(stats.keys()))
            roll = self.generator.upgrade_roll(stat, rarity, upgrade_level)
            cost = self.generator.upgrade_cost(rarity, upgrade_level)
            stats[stat] = max(1, int(stats.get(stat, 0)) + roll["amount"])
            log = self._parse_upgrade_log(row["upgrade_log"])
            log.append({
                "stat": stat, "amount": roll["amount"], "tier": roll["tier"],
                "high": bool(roll["high"]), "cost": cost,
            })
            conn.execute(
                "UPDATE artifacts SET stats = ?, upgrade_level = ?, upgrade_log = ? WHERE id = ?",
                (json.dumps(stats), upgrade_level + 1, json.dumps(log), aid),
            )
            conn.commit()
        return {
            "item": self.get_artifact_by_id(aid),
            "stat": stat,
            "amount": roll["amount"],
            "tier": roll["tier"],
            "high": bool(roll["high"]),
            "cost": cost,
        }

    def unupgrade_artifact(self, artifact_id: Any) -> Optional[Dict[str, Any]]:
        """Take the last upgrade back off, refunding part of its gold.

        Returns {'item', 'refund'} or None when there is nothing to undo."""
        try:
            aid = int(artifact_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM artifacts WHERE id = ?", (aid,)).fetchone()
            if row is None:
                return None
            log = self._parse_upgrade_log(row["upgrade_log"])
            upgrade_level = int(row["upgrade_level"] or 0)
            if upgrade_level <= 0 or not log:
                return None
            entry = log.pop()
            stats = self._parse_stats(row["stats"])
            stat = entry.get("stat")
            if stat in stats:
                stats[stat] = max(1, int(stats.get(stat, 0)) - int(entry.get("amount", 0)))
            refund = self.generator.unupgrade_refund(
                row["rarity"], int(entry.get("cost", 0)),
            )
            conn.execute(
                "UPDATE artifacts SET stats = ?, upgrade_level = ?, upgrade_log = ? WHERE id = ?",
                (json.dumps(stats), upgrade_level - 1, json.dumps(log), aid),
            )
            conn.commit()
        return {"item": self.get_artifact_by_id(aid), "refund": refund}

    def reroll_artifact_stats(self, artifact_id: Any) -> Optional[InventoryItem]:
        """Reroll the stat types entirely, with fresh random starting
        numbers. The item type and rarity stay; upgrades are reset."""
        try:
            aid = int(artifact_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM artifacts WHERE id = ?", (aid,)).fetchone()
            if row is None:
                return None
            stats = self.generator._roll_stats(row["item_type"], row["rarity"])
            conn.execute(
                "UPDATE artifacts SET stats = ?, upgrade_level = 0, upgrade_log = '[]' WHERE id = ?",
                (json.dumps(stats), aid),
            )
            conn.commit()
        return self.get_artifact_by_id(aid)

    def reroll_artifact_values(self, artifact_id: Any) -> Optional[InventoryItem]:
        """Keep the current stat types and the upgrade level, but re-roll
        where the numbers went — Genshin-style. Every upgrade is then
        applied again from scratch, each with a fresh low/mid/high roll, so
        a new reroll has a new chance at better numbers. The gold is
        spent either way."""
        try:
            aid = int(artifact_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM artifacts WHERE id = ?", (aid,)).fetchone()
            if row is None:
                return None
            stats = self._parse_stats(row["stats"])
            if not stats:
                return None
            rarity = row["rarity"]
            upgrade_level = int(row["upgrade_level"] or 0)
            # Fresh starting numbers for the same stat types…
            stats = self.generator.reroll_stat_values(stats, rarity)
            # …then re-apply every upgrade level with a brand-new roll.
            log = []
            for step in range(upgrade_level):
                stat = random.choice(list(stats.keys()))
                roll = self.generator.upgrade_roll(stat, rarity, step)
                stats[stat] = max(1, int(stats.get(stat, 0)) + roll["amount"])
                log.append({
                    "stat": stat, "amount": roll["amount"], "tier": roll["tier"],
                    "high": bool(roll["high"]),
                    "cost": self.generator.upgrade_cost(rarity, step),
                })
            conn.execute(
                "UPDATE artifacts SET stats = ?, upgrade_log = ? WHERE id = ?",
                (json.dumps(stats), json.dumps(log), aid),
            )
            conn.commit()
        return self.get_artifact_by_id(aid)

    # --- Items (JSON scan) ---
    def scan_items(self) -> List[InventoryItem]:
        self.items_dir.mkdir(parents=True, exist_ok=True)
        items: List[InventoryItem] = []
        for file_path in self.items_dir.iterdir():
            if not file_path.is_file() or file_path.suffix.lower() != ".json":
                continue
            try:
                data = json.loads(file_path.read_text(encoding="utf-8"))
            except Exception:
                continue
            img = data.get("image", "")
            img_path = self._resolve_image(img, file_path.parent)
            items.append(InventoryItem(
                uid=f"item:{file_path.stem}",
                name=data.get("name", file_path.stem.replace("_", " ").title()),
                category="item",
                item_type=data.get("type", "Misc"),
                description=data.get("description", ""),
                story=data.get("story", ""),
                rarity=data.get("rarity", "Common"),
                image_path=img_path,
                stats=data.get("stats", {}),
                count=data.get("count", 1),
                level=data.get("level", 1),
                source_file=str(file_path),
            ))
        return items

    def _resolve_image(self, img: str, fallback_dir: Path) -> str:
        if not img:
            return ""
        p = Path(img)
        if p.is_absolute() and p.exists():
            return str(p)
        cand = fallback_dir / img
        if cand.exists():
            return str(cand)
        cand2 = self.rp_root / "icons" / img
        if cand2.exists():
            return str(cand2)
        return str(cand)

    # --- Artifacts (DB read) ---
    def get_artifacts(self) -> List[InventoryItem]:
        items: List[InventoryItem] = []
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            for row in conn.execute("SELECT * FROM artifacts"):
                items.append(self._row_to_item(row))
        # Highest rarity first, then level, then name.
        rank = {r: i for i, r in enumerate(RARITIES)}
        items.sort(key=lambda it: (-rank.get(it.rarity, -1), -it.level, it.name))
        return items

    def all_inventory(self) -> List[InventoryItem]:
        return self.scan_items() + self.get_artifacts()

    # --- Removal ---
    def delete_artifact(self, uid: str):
        if not uid.startswith("artifact:"):
            return
        pk = uid.split(":", 1)[1]
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute("DELETE FROM artifacts WHERE id = ?", (pk,))
            conn.commit()

    # --- Shop stock ---
    def get_shop_stock(self) -> List[Dict[str, Any]]:
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute("SELECT * FROM shop_stock ORDER BY price ASC").fetchall()
        return [
            {
                "id": row["id"],
                "name": row["name"],
                "item_type": row["item_type"],
                "rarity": row["rarity"],
                "level": row["level"],
                "stats": self._parse_stats(row["stats"]),
                "price": row["price"],
                "description": row["description"] or "",
                "story": row["story"] or "",
            }
            for row in rows
        ]

    def restock_shop(self, player_level: int = 1, count: Optional[int] = None):
        """Reroll the shop shelves with fresh generated artifacts.
        Artifacts have no level — `player_level` is accepted for
        compatibility and ignored."""
        count = self.SHOP_STOCK_SIZE if count is None else max(0, int(count))
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute("DELETE FROM shop_stock")
            for _ in range(count):
                a = self.generator.generate(rarity=self.generator.roll_shop_rarity())
                conn.execute("""
                    INSERT INTO shop_stock
                        (name, item_type, rarity, level, stats, price, description, story)
                    VALUES
                        (:name, :item_type, :rarity, :level, :stats, :price, :description, :story)
                """, {
                    **a,
                    "stats": json.dumps(a["stats"]),
                    "price": self.generator.price(a["rarity"]),
                })
            conn.commit()

    def buy_from_shop(self, stock_id: Any) -> Optional[InventoryItem]:
        """Move an artifact from the shop shelves into the inventory."""
        try:
            stock_id = int(stock_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT * FROM shop_stock WHERE id = ?", (stock_id,)
            ).fetchone()
            if row is None:
                return None
            conn.execute("DELETE FROM shop_stock WHERE id = ?", (stock_id,))
            payload = {
                "name": row["name"],
                "item_type": row["item_type"],
                "rarity": row["rarity"],
                "level": row["level"],
                "stats": row["stats"],
                "source": "shop",
                "description": row["description"] or "",
                "story": row["story"] or "",
            }
            new_id = self._insert_artifact(conn, payload)
            conn.commit()
        return InventoryItem(
            uid=f"artifact:{new_id}",
            name=row["name"],
            category="artifact",
            item_type=row["item_type"],
            description=row["description"] or "",
            story=row["story"] or "",
            rarity=row["rarity"],
            image_path="",
            stats=self._parse_stats(row["stats"]),
            count=1,
            level=row["level"],
            source_file=str(self.db_path),
            source="shop",
        )

    def buy_common_package(self, player_level: int = 1) -> List[InventoryItem]:
        """The shop's bulk deal: PACKAGE_SIZE common artifacts at once.
        Artifacts have no level — `player_level` is accepted for
        compatibility and ignored."""
        items: List[InventoryItem] = []
        for _ in range(self.PACKAGE_SIZE):
            items.extend(self.generate_artifacts(
                count=1, rarity="Common", source="shop",
            ))
        return items

    # --- Supplies (shop catalogue from shop/*.json, stored as counts) ---
    def supply_catalog(self) -> List[Dict[str, Any]]:
        """The shop's supply list (id, name, price, description) — loaded
        from the shop folder's JSON files, with the built-ins as fallback."""
        return self.supplies

    def get_supply_counts(self) -> Dict[str, int]:
        with sqlite3.connect(str(self.db_path)) as conn:
            rows = conn.execute("SELECT id, count FROM supplies").fetchall()
        return {row[0]: int(row[1] or 0) for row in rows}

    def get_supplies(self) -> List[InventoryItem]:
        """The whole supply catalogue with the player's owned counts."""
        counts = self.get_supply_counts()
        return [
            InventoryItem(
                uid=f"supply:{spec['id']}",
                name=spec["name"],
                category="supply",
                item_type="Supply",
                description=spec["description"],
                story="",
                rarity="Common",
                image_path="",
                stats={},
                count=counts.get(spec["id"], 0),
                level=1,
                source="shop",
            )
            for spec in self.supplies
        ]

    def buy_supply(self, supply_id: str, amount: int = 1) -> Optional[InventoryItem]:
        """Add supplies to the player's stash; returns the updated entry."""
        amount = max(1, int(amount))
        spec = next((s for s in self.supplies if s["id"] == supply_id), None)
        if spec is None:
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute(
                "INSERT INTO supplies (id, count) VALUES (?, ?) "
                "ON CONFLICT(id) DO UPDATE SET count = count + ?",
                (supply_id, amount, amount),
            )
            conn.commit()
        return self.get_supply(supply_id)

    def get_supply(self, supply_id: str) -> Optional[InventoryItem]:
        counts = self.get_supply_counts()
        spec = next((s for s in self.supplies if s["id"] == supply_id), None)
        if spec is None:
            return None
        return InventoryItem(
            uid=f"supply:{spec['id']}",
            name=spec["name"],
            category="supply",
            item_type="Supply",
            description=spec["description"],
            story="",
            rarity="Common",
            image_path="",
            stats={},
            count=counts.get(spec["id"], 0),
            level=1,
            source="shop",
        )

    def consume_supply(self, supply_id: str, amount: int = 1) -> Optional[InventoryItem]:
        """Use up supplies; the entry disappears once the count hits 0."""
        amount = max(1, int(amount))
        counts = self.get_supply_counts()
        if supply_id not in counts:
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            remaining = max(0, counts[supply_id] - amount)
            if remaining <= 0:
                conn.execute("DELETE FROM supplies WHERE id = ?", (supply_id,))
            else:
                conn.execute("UPDATE supplies SET count = ? WHERE id = ?", (remaining, supply_id))
            conn.commit()
        item = self.get_supply(supply_id)
        return item if item is not None and item.count > 0 else None

    def sacrifice_artifacts(self, ids: List[Any]) -> Optional[InventoryItem]:
        """Fuse SACRIFICE_PER_FUSION artifacts of one rarity into a single
        artifact of the next rarity with fresh random stats.

        Returns the forged artifact, or None when the sacrifice is invalid
        (wrong count, missing rows, mixed rarities, or Mythic input)."""
        clean: List[int] = []
        for value in ids or []:
            try:
                clean.append(int(value))
            except (TypeError, ValueError):
                return None
        if len(clean) != SACRIFICE_PER_FUSION:
            return None
        placeholders = ",".join("?" * len(clean))
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                f"SELECT * FROM artifacts WHERE id IN ({placeholders})", clean
            ).fetchall()
            if len(rows) != SACRIFICE_PER_FUSION:
                return None
            rarities = {row["rarity"] for row in rows}
            if len(rarities) != 1:
                return None
            rarity = rarities.pop()
            if rarity not in RARITIES or rarity == RARITIES[-1]:
                return None  # Mythic has no higher rank
            conn.execute(f"DELETE FROM artifacts WHERE id IN ({placeholders})", clean)
            conn.commit()
        next_rarity = RARITIES[RARITIES.index(rarity) + 1]
        forged = self.generate_artifacts(
            count=1, rarity=next_rarity, source="forge",
        )
        return forged[0] if forged else None
